pub(crate) fn pa_dump_sig(mut t: &mut String, txt: &mut crate::port::Cells, sg: &mut crate::port::Cells, row: i32) -> i32 {
    let at: i32 = row * SG_STRIDE;
    let mut k: i32 = 0;
    crate::port::text_ascii(t, "{\"field\":");
    crate::port::text_i32(t, crate::port::cells_at(sg, at));
    crate::port::text_ascii(t, ",\"annot\":");
    crate::port::text_i32(t, crate::port::cells_at(sg, at + 1));
    crate::port::text_ascii(t, ",\"page\":");
    crate::port::text_i32(t, crate::port::cells_at(sg, at + 2));
    if crate::port::cells_at(sg, at + 2) >= 0 {
        crate::port::text_ascii(t, ",\"rect\":");
        px_json_box(t, sg, at + 3);
    }
    crate::port::text_ascii(t, ",\"name\":");
    px_json_run(t, txt, crate::port::cells_at(sg, at + 7), crate::port::cells_at(sg, at + 8));
    crate::port::text_ascii(t, ",\"m\":");
    px_json_run(t, txt, crate::port::cells_at(sg, at + 9), crate::port::cells_at(sg, at + 10));
    if crate::port::cells_at(sg, at + 11) >= 0 {
        crate::port::text_ascii(t, ",\"date\":[");
        k = 0;
        while k < 7 {
            if k > 0 {
                crate::port::text_ascii(t, ",");
            }
            crate::port::text_i32(t, crate::port::cells_at(sg, (at + 11) + k));
            k += 1;
        }
        crate::port::text_ascii(t, "]");
    }
    crate::port::text_ascii(t, ",\"reason\":");
    px_json_run(t, txt, crate::port::cells_at(sg, at + 18), crate::port::cells_at(sg, at + 19));
    crate::port::text_ascii(t, ",\"location\":");
    px_json_run(t, txt, crate::port::cells_at(sg, at + 20), crate::port::cells_at(sg, at + 21));
    crate::port::text_ascii(t, ",\"contact\":");
    px_json_run(t, txt, crate::port::cells_at(sg, at + 22), crate::port::cells_at(sg, at + 23));
    crate::port::text_ascii(t, ",\"filter\":");
    px_json_run(t, txt, crate::port::cells_at(sg, at + 24), crate::port::cells_at(sg, at + 25));
    crate::port::text_ascii(t, ",\"subfilter\":");
    px_json_run(t, txt, crate::port::cells_at(sg, at + 26), crate::port::cells_at(sg, at + 27));
    crate::port::text_ascii(t, ",\"range\":[");
    k = 0;
    while k < 4 {
        if k > 0 {
            crate::port::text_ascii(t, ",");
        }
        crate::port::text_i32(t, crate::port::cells_at(sg, (at + 28) + k));
        k += 1;
    }
    crate::port::text_ascii(t, "],\"contents\":");
    crate::port::text_i32(t, crate::port::cells_at(sg, at + 32));
    crate::port::text_ascii(t, ",\"bits\":");
    crate::port::text_i32(t, crate::port::cells_at(sg, at + 33));
    crate::port::text_ascii(t, "}");
    return 0;
}
pub fn pa_dump(mut t: &mut String, txt: &mut crate::port::Cells, an: &mut crate::port::Cells, aq: &mut crate::port::Cells, fd: &mut crate::port::Cells, sg: &mut crate::port::Cells) -> i32 {
    // Annotations, fields and signatures as one canonical JSON object, in row order:
    // `{"annots":[..],"fields":[..],"sigs":[..]}`. Not a public contract (the
    // Model says what it needs of these); it is what the laws and the oracle compare.
    let na: i32 = crate::port::cells_len(an) / AN_STRIDE;
    let nf: i32 = crate::port::cells_len(fd) / FD_STRIDE;
    let ns: i32 = crate::port::cells_len(sg) / SG_STRIDE;
    let mut i: i32 = 0;
    crate::port::text_ascii(t, "{\"annots\":[");
    while i < na {
        if i > 0 {
            crate::port::text_ascii(t, ",");
        }
        pa_dump_annot(t, txt, an, aq, i);
        i += 1;
    }
    crate::port::text_ascii(t, "],\"fields\":[");
    i = 0;
    while i < nf {
        if i > 0 {
            crate::port::text_ascii(t, ",");
        }
        pa_dump_field(t, txt, fd, i);
        i += 1;
    }
    crate::port::text_ascii(t, "],\"sigs\":[");
    i = 0;
    while i < ns {
        if i > 0 {
            crate::port::text_ascii(t, ",");
        }
        pa_dump_sig(t, txt, sg, i);
        i += 1;
    }
    crate::port::text_ascii(t, "]}");
    return 0;
}
